import math
def priority(task, state, b=1.0, m=1.0, map_r=1.0, reduce_r=1.0, join_r=1.0, other_r=1.0, map_w=1.0, reduce_w=1.0, join_w=1.0, other_w=1.0):
    est = max(task.estimated_runtime, 1e-6)
    wait = max(0.0, state.now - task.release)
    if task.task_type == 'map':
        rm = map_r
        wm = map_w
    elif task.task_type == 'reduce':
        rm = reduce_r
        wm = reduce_w
    elif task.task_type == 'join':
        rm = join_r
        wm = join_w
    else:
        rm = other_r
        wm = other_w
    est_adj = max(est * rm, 1e-6)
    weight = task.weight * wm
    if task.tenant == 'premium':
        weight *= m
    return weight / est_adj * (1.0 + b * wait / est_adj)

import math
def priority(task, state, k=2.0, b=1.0, c=0.5, premium=2.0,
             map_w=1.0, reduce_w=1.0, join_w=1.0, other_w=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, state.now - task.release)
    slack = max(0.0, task.due - state.now - est)
    w = task.weight
    if task.tenant == 'premium':
        w *= premium
    if task.task_type == 'map':
        w *= map_w
    elif task.task_type == 'reduce':
        w *= reduce_w
    elif task.task_type == 'join':
        w *= join_w
    else:
        w *= other_w
    urg = math.exp(-slack / max(k * mean, 1e-6))
    age = 1.0 + b * wait / est + c * wait / mean
    return (w / est) * age * max(urg, 1e-6)

